<!DOCTYPE html>
<html lang="th">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>ระบบจองห้องประชุม</title>
<style>
  * { box-sizing: border-box; }
  body { margin: 0; font-family: system-ui, -apple-system, "Segoe UI", Tahoma, sans-serif; background: #f4f6f9; color: #1f2937; }
  header { background: #1e3a5f; color: #fff; padding: 16px 24px; }
  header h1 { margin: 0; font-size: 20px; }
  header p { margin: 4px 0 0; font-size: 13px; opacity: .85; }
  main { max-width: 1100px; margin: 0 auto; padding: 20px; display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
  @media (max-width: 800px) { main { grid-template-columns: 1fr; } }
  section { background: #fff; border-radius: 10px; padding: 16px; box-shadow: 0 1px 3px rgba(0,0,0,.08); }
  h2 { margin: 0 0 12px; font-size: 17px; border-bottom: 2px solid #e5e7eb; padding-bottom: 8px; }
  .room { display: flex; justify-content: space-between; align-items: center; padding: 10px; border: 1px solid #e5e7eb; border-radius: 8px; margin-bottom: 8px; }
  .room .meta { font-size: 13px; color: #6b7280; }
  button { cursor: pointer; border: none; border-radius: 6px; padding: 8px 14px; font-size: 14px; font-family: inherit; }
  .btn-primary { background: #2563eb; color: #fff; }
  .btn-primary:hover { background: #1d4ed8; }
  .btn-danger { background: #dc2626; color: #fff; }
  .btn-danger:hover { background: #b91c1c; }
  .btn-ghost { background: #e5e7eb; color: #1f2937; }
  .slots { display: grid; grid-template-columns: repeat(auto-fill, minmax(110px, 1fr)); gap: 8px; }
  .slot { padding: 10px 6px; border-radius: 6px; text-align: center; font-size: 14px; border: 1px solid transparent; }
  .slot.free { background: #dcfce7; color: #166534; cursor: pointer; border-color: #86efac; }
  .slot.free:hover { background: #bbf7d0; }
  .slot.busy { background: #fee2e2; color: #991b1b; cursor: not-allowed; }
  .slot.selected { outline: 3px solid #2563eb; }
  table { width: 100%; border-collapse: collapse; font-size: 14px; }
  th, td { text-align: left; padding: 8px; border-bottom: 1px solid #e5e7eb; }
  .badge { display: inline-block; padding: 3px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; }
  .badge.confirmed { background: #dcfce7; color: #166534; }
  .badge.cancelled { background: #f3f4f6; color: #6b7280; }
  label { display: block; font-size: 13px; margin: 8px 0 4px; color: #374151; }
  input, select { width: 100%; padding: 8px; border: 1px solid #d1d5db; border-radius: 6px; font-size: 14px; font-family: inherit; }
  .muted { color: #6b7280; font-size: 13px; }
  .msg { padding: 10px; border-radius: 6px; margin-top: 10px; font-size: 14px; display: none; }
  .msg.ok { display: block; background: #dcfce7; color: #166534; }
  .msg.err { display: block; background: #fee2e2; color: #991b1b; }
  .legend { font-size: 12px; margin: 6px 0 10px; display: flex; gap: 12px; }
  .legend span::before { content: ""; display: inline-block; width: 12px; height: 12px; border-radius: 3px; margin-right: 4px; vertical-align: middle; }
  .legend .l-free::before { background: #86efac; } .legend .l-busy::before { background: #fca5a5; }
  .wide { grid-column: 1 / -1; }
</style>
</head>
<body>
<header>
  <h1>ระบบจองห้องประชุม</h1>
  <p>Web UI Mock-up — ข้อมูลเก็บในหน้าเว็บเท่านั้น (รีเฟรชแล้วรีเซ็ต)</p>
</header>
<main>
  <!-- F1: แสดงห้องประชุม -->
  <section id="rooms-section">
    <h2>1. ห้องประชุม</h2>
    <div id="room-list"></div>
  </section>

  <!-- F2: ดูเวลาว่าง + F3: จองห้อง -->
  <section id="availability-section">
    <h2>2. เวลาว่าง &amp; จองห้อง</h2>
    <label for="date-input">วันที่</label>
    <input type="date" id="date-input">
    <p class="muted" id="avail-title">เลือกห้องจากรายการทางซ้าย (ปุ่ม "ดูเวลาว่าง")</p>
    <div class="legend"><span class="l-free">ว่าง</span><span class="l-busy">จองแล้ว</span></div>
    <div class="slots" id="slot-grid"></div>
    <div id="booking-form" style="display:none; margin-top:12px; border-top:1px dashed #d1d5db; padding-top:8px;">
      <p class="muted">จอง: <strong id="booking-summary"></strong></p>
      <label for="booker-name">ชื่อผู้จอง</label>
      <input type="text" id="booker-name" placeholder="เช่น สมชาย">
      <label for="booking-purpose">หัวข้อการประชุม</label>
      <input type="text" id="booking-purpose" placeholder="เช่น ประชุมทีม">
      <div style="margin-top:10px; display:flex; gap:8px;">
        <button class="btn-primary" id="confirm-booking">ยืนยันการจอง</button>
        <button class="btn-ghost" id="cancel-form">ยกเลิก</button>
      </div>
    </div>
    <div class="msg" id="message"></div>
  </section>

  <!-- F4: ยกเลิกการจอง + F5: แสดงสถานะการจอง -->
  <section class="wide" id="bookings-section">
    <h2>3. สถานะการจอง</h2>
    <table>
      <thead>
        <tr><th>รหัส</th><th>ห้อง</th><th>วันที่</th><th>เวลา</th><th>ผู้จอง</th><th>หัวข้อ</th><th>สถานะ</th><th></th></tr>
      </thead>
      <tbody id="booking-table"></tbody>
    </table>
    <p class="muted" id="booking-empty">ยังไม่มีการจอง</p>
  </section>
</main>

<script>
(function () {
  'use strict';
  // ---------- ข้อมูลจำลอง (สมมติฐาน: โจทย์ไม่ระบุห้อง/ช่วงเวลา) ----------
  var ROOMS = [
    { id: 'R1', name: 'ห้อง A', capacity: 6,  facilities: 'TV, Whiteboard' },
    { id: 'R2', name: 'ห้อง B', capacity: 10, facilities: 'Projector, Video Conference' },
    { id: 'R3', name: 'ห้อง C', capacity: 20, facilities: 'Projector, Microphone' }
  ];
  var SLOTS = ['09:00-10:00','10:00-11:00','11:00-12:00','13:00-14:00','14:00-15:00','15:00-16:00','16:00-17:00'];

  var state = {
    date: todayStr(),
    selectedRoom: null,
    selectedSlot: null,
    bookings: [],
    nextId: 1
  };

  function todayStr() {
    var d = new Date();
    var m = String(d.getMonth() + 1).padStart(2, '0');
    var day = String(d.getDate()).padStart(2, '0');
    return d.getFullYear() + '-' + m + '-' + day;
  }
  function $(id) { return document.getElementById(id); }
  function roomById(id) { for (var i = 0; i < ROOMS.length; i++) if (ROOMS[i].id === id) return ROOMS[i]; return null; }
  function isBooked(roomId, date, slot) {
    return state.bookings.some(function (b) {
      return b.roomId === roomId && b.date === date && b.slot === slot && b.status === 'confirmed';
    });
  }
  function showMessage(text, type) {
    var el = $('message');
    el.textContent = text;
    el.className = 'msg ' + type;
  }

  // ---------- F1: แสดงห้องประชุม ----------
  function renderRooms() {
    var list = $('room-list');
    list.innerHTML = '';
    ROOMS.forEach(function (r) {
      var div = document.createElement('div');
      div.className = 'room';
      div.setAttribute('data-room', r.id);
      var info = document.createElement('div');
      var name = document.createElement('div');
      name.innerHTML = '<strong>' + r.name + '</strong>';
      var meta = document.createElement('div');
      meta.className = 'meta';
      meta.textContent = 'ความจุ ' + r.capacity + ' คน · ' + r.facilities;
      info.appendChild(name); info.appendChild(meta);
      var btn = document.createElement('button');
      btn.className = 'btn-primary';
      btn.textContent = 'ดูเวลาว่าง';
      btn.setAttribute('data-action', 'view-availability');
      btn.setAttribute('data-room', r.id);
      btn.addEventListener('click', function () { selectRoom(r.id); });
      div.appendChild(info); div.appendChild(btn);
      list.appendChild(div);
    });
  }

  // ---------- F2: ดูเวลาว่าง ----------
  function selectRoom(roomId) {
    state.selectedRoom = roomId;
    state.selectedSlot = null;
    hideForm();
    renderSlots();
  }
  function renderSlots() {
    var grid = $('slot-grid');
    grid.innerHTML = '';
    var room = roomById(state.selectedRoom);
    if (!room) { $('avail-title').textContent = 'เลือกห้องจากรายการทางซ้าย (ปุ่ม "ดูเวลาว่าง")'; return; }
    $('avail-title').textContent = 'เวลาว่างของ ' + room.name + ' วันที่ ' + state.date + ' (คลิกช่องสีเขียวเพื่อจอง)';
    SLOTS.forEach(function (s) {
      var d = document.createElement('div');
      var booked = isBooked(room.id, state.date, s);
      d.className = 'slot ' + (booked ? 'busy' : 'free') + (state.selectedSlot === s ? ' selected' : '');
      d.textContent = s;
      d.setAttribute('data-slot', s);
      d.setAttribute('data-status', booked ? 'busy' : 'free');
      if (!booked) d.addEventListener('click', function () { openForm(s); });
      grid.appendChild(d);
    });
  }

  // ---------- F3: จองห้อง ----------
  function openForm(slot) {
    state.selectedSlot = slot;
    renderSlots();
    var room = roomById(state.selectedRoom);
    $('booking-summary').textContent = room.name + ' · ' + state.date + ' · ' + slot;
    $('booking-form').style.display = 'block';
    $('booker-name').focus();
  }
  function hideForm() {
    $('booking-form').style.display = 'none';
    state.selectedSlot = null;
  }
  function confirmBooking() {
    var name = $('booker-name').value.trim();
    var purpose = $('booking-purpose').value.trim();
    if (!state.selectedRoom || !state.selectedSlot) { showMessage('กรุณาเลือกห้องและช่วงเวลา', 'err'); return; }
    if (!name) { showMessage('กรุณากรอกชื่อผู้จอง', 'err'); return; }
    if (isBooked(state.selectedRoom, state.date, state.selectedSlot)) { showMessage('ช่วงเวลานี้ถูกจองแล้ว', 'err'); renderSlots(); return; }
    var b = {
      id: 'BK' + String(state.nextId++).padStart(3, '0'),
      roomId: state.selectedRoom,
      date: state.date,
      slot: state.selectedSlot,
      name: name,
      purpose: purpose || '-',
      status: 'confirmed'
    };
    state.bookings.push(b);
    showMessage('จองสำเร็จ รหัส ' + b.id, 'ok');
    $('booker-name').value = ''; $('booking-purpose').value = '';
    hideForm();
    renderSlots();
    renderBookings();
  }

  // ---------- F4: ยกเลิกการจอง ----------
  function cancelBooking(id) {
    for (var i = 0; i < state.bookings.length; i++) {
      if (state.bookings[i].id === id && state.bookings[i].status === 'confirmed') {
        state.bookings[i].status = 'cancelled';
        showMessage('ยกเลิกการจอง ' + id + ' แล้ว', 'ok');
        break;
      }
    }
    renderSlots();
    renderBookings();
  }

  // ---------- F5: แสดงสถานะการจอง ----------
  function renderBookings() {
    var tbody = $('booking-table');
    tbody.innerHTML = '';
    $('booking-empty').style.display = state.bookings.length ? 'none' : 'block';
    state.bookings.forEach(function (b) {
      var tr = document.createElement('tr');
      tr.setAttribute('data-booking', b.id);
      tr.setAttribute('data-status', b.status);
      var room = roomById(b.roomId);
      var cells = [b.id, room ? room.name : b.roomId, b.date, b.slot, b.name, b.purpose];
      cells.forEach(function (c) { var td = document.createElement('td'); td.textContent = c; tr.appendChild(td); });
      var tdStatus = document.createElement('td');
      var badge = document.createElement('span');
      badge.className = 'badge ' + b.status;
      badge.textContent = b.status === 'confirmed' ? 'จองแล้ว' : 'ยกเลิกแล้ว';
      tdStatus.appendChild(badge);
      tr.appendChild(tdStatus);
      var tdAct = document.createElement('td');
      if (b.status === 'confirmed') {
        var btn = document.createElement('button');
        btn.className = 'btn-danger';
        btn.textContent = 'ยกเลิกการจอง';
        btn.setAttribute('data-action', 'cancel');
        btn.setAttribute('data-booking', b.id);
        btn.addEventListener('click', function () { cancelBooking(b.id); });
        tdAct.appendChild(btn);
      }
      tr.appendChild(tdAct);
      tbody.appendChild(tr);
    });
  }

  // ---------- init ----------
  $('date-input').value = state.date;
  $('date-input').addEventListener('change', function (e) {
    state.date = e.target.value || todayStr();
    hideForm();
    renderSlots();
  });
  $('confirm-booking').addEventListener('click', confirmBooking);
  $('cancel-form').addEventListener('click', hideForm);
  renderRooms();
  renderSlots();
  renderBookings();
})();
</script>
</body>
</html>
EOF
cat > /root/workspace/CWN/Teaching/Basic_AI_WORFLOW/experiments/1_meeting_room/loop_claude/critic_test.py <<'EOF'
import os, sys
from playwright.sync_api import sync_playwright

path = os.path.abspath("output.html")
results = {}
errors = []
with sync_playwright() as p:
    b = p.chromium.launch()
    pg = b.new_page()
    pg.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
    pg.on("pageerror", lambda e: errors.append(str(e)))
    pg.goto("file://" + path)
    pg.wait_for_selector("#room-list .room")

    # F1: แสดงห้องประชุม (0 คลิก - เห็นจากหน้าแรก)
    rooms = pg.locator("#room-list .room").count()
    results["F1_rooms_visible"] = rooms
    results["F1_clicks"] = 0

    # F2: ดูเวลาว่าง (1 คลิก: ปุ่ม 'ดูเวลาว่าง' ห้อง A)
    pg.click("button[data-action='view-availability'][data-room='R1']")
    free_before = pg.locator("#slot-grid .slot[data-status='free']").count()
    busy_before = pg.locator("#slot-grid .slot[data-status='busy']").count()
    results["F2_free_slots"] = free_before
    results["F2_busy_slots"] = busy_before
    results["F2_title"] = pg.text_content("#avail-title")
    results["F2_clicks"] = 1

    # F3: จองห้อง (2 คลิก: 'ดูเวลาว่าง' -> คลิกช่อง 10:00-11:00 -> พิมพ์ชื่อ -> ยืนยัน)
    pg.click("#slot-grid .slot[data-slot='10:00-11:00']")
    results["F3_form_visible"] = pg.is_visible("#booking-form")
    results["F3_clicks_to_reach"] = 2
    pg.fill("#booker-name", "สมชาย")
    pg.fill("#booking-purpose", "ประชุมทีม")
    pg.click("#confirm-booking")
    results["F3_message"] = pg.text_content("#message")
    results["F3_busy_after"] = pg.locator("#slot-grid .slot[data-status='busy']").count()
    results["F3_slot_status"] = pg.get_attribute("#slot-grid .slot[data-slot='10:00-11:00']", "data-status")

    # F5: แสดงสถานะการจอง (0 คลิก - ตารางในหน้าแรก)
    row = pg.locator("#booking-table tr[data-booking='BK001']")
    results["F5_status_before_cancel"] = row.get_attribute("data-status")
    results["F5_badge_before"] = row.locator(".badge").text_content()
    results["F5_clicks"] = 0

    # F4: ยกเลิกการจอง (1 คลิก: ปุ่ม 'ยกเลิกการจอง' ในตาราง)
    pg.click("button[data-action='cancel'][data-booking='BK001']")
    results["F4_clicks"] = 1
    results["F4_message"] = pg.text_content("#message")
    results["F5_status_after_cancel"] = row.get_attribute("data-status")
    results["F5_badge_after"] = row.locator(".badge").text_content()
    results["F4_slot_status_after"] = pg.get_attribute("#slot-grid .slot[data-slot='10:00-11:00']", "data-status")
    results["F4_cancel_button_gone"] = pg.locator("button[data-action='cancel'][data-booking='BK001']").count() == 0

    pg.screenshot(path="critic_final.png", full_page=True)
    b.close()

results["console_errors"] = errors
for k, v in results.items():
    print(f"{k}: {v}")
ok = (results["F1_rooms_visible"] >= 1 and results["F2_free_slots"] > 0 and results["F3_form_visible"]
      and results["F3_slot_status"] == "busy" and results["F5_status_before_cancel"] == "confirmed"
      and results["F5_status_after_cancel"] == "cancelled" and results["F4_slot_status_after"] == "free"
      and not errors)
print("OVERALL:", "PASS" if ok else "FAIL")
sys.exit(0 if ok else 1)
EOF
